package com.aicharacter.v3;
/** Converts biological condition and mechanical work into force capacity, fatigue and joint mobility. */
public final class MusculoskeletalEngine{private MusculoskeletalEngine(){}
 public static void advance(WorldState s,double dt){if(s==null||dt<=0)return;if(s.musculoskeletal==null)s.musculoskeletal=new MusculoskeletalState();MusculoskeletalState m=s.musculoskeletal;double speed=s.girlTravel!=null&&s.girlTravel.active?s.girlTravel.lastSpeed:0,work=Math.max(0,Math.min(1,speed/92.0));double pain=s.body==null?0:s.body.pain/100.0,energy=s.body==null?1:s.body.energy/100.0;double load=work*(.35+.65*(s.girlPhysics==null?1:s.girlPhysics.groundReaction/Math.max(1,s.girlPhysics.massKg*WholeBodyPhysicsEngine.GRAVITY)));m.legFatigue=follow(m.legFatigue,Math.min(1,load*.72+(1-energy)*.45),dt,18);m.coreFatigue=follow(m.coreFatigue,Math.min(1,load*.42+(1-energy)*.32),dt,28);m.jointMobility=Math.max(.45,1-pain*.42-Math.min(.18,m.impactLoad*.02));m.legForceCapacity=Math.max(.32,(1-m.legFatigue*.48)*(1-pain*.35)*m.jointMobility);m.coreForceCapacity=Math.max(.35,(1-m.coreFatigue*.40)*(1-pain*.28));m.armForceCapacity=Math.max(.4,(1-m.coreFatigue*.20)*(1-pain*.22));m.impactLoad=Math.max(0,m.impactLoad*Math.exp(-dt/12.0));}
 public static double locomotorCapacity(WorldState s){MusculoskeletalState m=s==null?null:s.musculoskeletal;return m==null?1:Math.max(.28,Math.min(1,m.legForceCapacity*(.72+.28*m.coreForceCapacity)));}
 private static double follow(double v,double t,double dt,double tau){double k=1-Math.exp(-dt/Math.max(.1,tau));return Math.max(0,Math.min(1,v+(t-v)*k));}
}